<script setup>
import { computed,onMounted,onUnmounted,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import StatusTag from '../components/StatusTag.vue';import { getTaskTypeText } from '../mock/tasks.js';import { getAdvisorTask } from '../api/taskApi.js';import { adaptTaskEnvelope } from '../adapters/taskAdapter.js';import { getApiErrorMessage } from '../utils/apiFeedback.js';import { getServerNowMs } from '../services/systemTimeService.js'
const route=useRoute();const router=useRouter();const task=ref(null);let deadlineTimer=null;async function loadTask(schedule=true){try{const payload=await getAdvisorTask(Number(route.params.id));task.value=adaptTaskEnvelope(payload);console.info('[advisor-task-detail]',{id:task.value?.id,status:task.value?.status,registrationDeadlineRaw:payload?.task?.registration_deadline??payload?.registration_deadline,registrationDeadline:task.value?.registrationDeadline});if(schedule)scheduleDeadlineRefresh()}catch(error){window.alert(getApiErrorMessage(error,'任务详情加载失败'))}}function scheduleDeadlineRefresh(){clearTimeout(deadlineTimer);const deadline=Date.parse(task.value?.registrationDeadline);const delay=deadline-getServerNowMs();if(!Number.isFinite(delay)||delay<=0)return;const maxDelay=2147480000;deadlineTimer=delay>maxDelay?setTimeout(scheduleDeadlineRefresh,maxDelay):setTimeout(()=>loadTask(false),delay+1000)}onMounted(()=>loadTask());onUnmounted(()=>clearTimeout(deadlineTimer));const canViewApplicants=computed(()=>['published','registration_open','registration_closed','selection_pending','leader_pending','task_in_progress','result_submitted','result_approved','completed'].includes(task.value?.status));const canSelect=computed(()=>task.value?.status==='selection_pending');function back(){router.push('/teacher/tasks')}
</script>
<template><main class="page"><div class="content"><template v-if="task"><header><div><p class="eyebrow">T102 · TASK DETAIL</p><h1>{{ task.title }}</h1><p>{{ task.taskId }}</p></div><StatusTag :status="task.status" /></header><section class="card"><h2>任务信息</h2><dl><div><dt>任务类型</dt><dd>{{ getTaskTypeText(task.taskType) }}</dd></div><div><dt>报名截止时间</dt><dd>{{ task.registrationDeadline }}</dd></div><div><dt>报名人数</dt><dd>{{ task.applicants?.length||0 }} 人</dd></div><div><dt>已选中人数</dt><dd>{{ task.selectedStudents?.length||0 }} 人</dd></div><div><dt>当前队长</dt><dd>{{ task.leaderName||'--' }}</dd></div><div class="wide"><dt>任务说明</dt><dd>{{ task.description }}</dd></div></dl></section><div class="actions"><button @click="back">返回</button><RouterLink v-if="canViewApplicants" :to="`/teacher/tasks/${task.taskId}/applicants`">查看报名学生</RouterLink><RouterLink v-if="canSelect" :to="`/teacher/tasks/${task.taskId}/applicants/select`">筛选学生</RouterLink><RouterLink v-if="['leader_pending','task_in_progress'].includes(task.status)" :to="`/teacher/tasks/${task.taskId}/leader`">指定队长</RouterLink><RouterLink to="/teacher/confirm/results">查看任务成果</RouterLink></div></template><section v-else class="card empty"><h1>未找到任务</h1><button @click="back">返回</button></section></div></main></template>
<style scoped>.page{min-height:100vh;padding:40px 24px;background:#f3f6fb}.content{width:min(100%,900px);margin:auto}header{display:flex;justify-content:space-between;gap:20px;margin-bottom:20px}h1{margin:0}header p{color:#64748b}.eyebrow{margin:0 0 6px;color:#2563eb!important;font-size:12px;font-weight:800;letter-spacing:.12em}.card{padding:22px;border:1px solid #e2e8f0;border-radius:14px;background:#fff}.card h2{margin:0 0 18px}dl{display:grid;grid-template-columns:repeat(2,1fr);gap:18px;margin:0}.wide{grid-column:1/-1}dt{color:#64748b;font-size:13px}dd{margin:5px 0 0;font-weight:600;line-height:1.7}.actions{display:flex;justify-content:flex-end;gap:10px;margin-top:18px}.actions a,.actions button,.empty button{padding:10px 16px;border:1px solid #cbd5e1;border-radius:9px;color:#2563eb;background:#fff;font:inherit;font-weight:700;text-decoration:none;cursor:pointer}.empty{text-align:center}@media(max-width:650px){.page{padding:24px 14px}header{flex-direction:column}dl{grid-template-columns:1fr}.wide{grid-column:auto}.actions{flex-wrap:wrap}}</style>
